    assert len(st.players[2].graveyard.cards) == before_graveyard_size
    assert len(st.players[2].arsenal.cards) == before_arsenal_size
    assert len(st.players[2].banished.cards) == before_banished_size
    assert len(st.players[2].hand.cards) == before_hand_size
    assert len(st.players[2].chest.cards) == before_chest_size
    assert len(st.players[2].arms.cards) == before_arms_size
    assert len(st.players[2].weapon1.cards) == before_weapon1_size
    assert len(st.players[2].permanents.cards) == before_permanents_size

