# --- blanch_yellow ---
def test_blanch_yellow_on_hit_removes_colors():
    st = _make_state(); st.card_db = DB
    card = _card("blanch_yellow")
    st.players[1].weapon1.add(card)
    attack(st, card)
    hit(st)
    # Assuming the opponent hero has a card in their hand
    opponent_hand = st.players[2].hand.cards
    if opponent_hand:
        before_colors = opponent_hand[0].colors
        assert before_colors, "The opponent's card should have colors before Blanch is played."
        # Dispatch the static ability to remove colors
        dispatch(st, "STATIC", "blanch_yellow", card=card)
        after_colors = opponent_hand[0].colors
        assert not after_colors, "The opponent's card should lose all colors after Blanch is played."

def test_blanch_yellow_on_hit_defense_value():
    st = _make_state(); st.card_db = DB
    card = _card("blanch_yellow")
    st.players[1].weapon1.add(card)
    attack(st, card)
    hit(st)
    # Assuming the opponent hero has a card in their hand
    opponent_hand = st.players[2].hand.cards
    if opponent_hand:
        before_defense = opponent_hand[0].defense
        # Dispatch the static ability to modify defense value
        dispatch(st, "STATIC", "blanch_yellow", card=card)
        after_defense = opponent_hand[0].defense
        assert after_defense == before_defense - 1, "The opponent's card's defense value should be reduced by 1 after Blanch is played."
